import{_ as a,o as t,c as n,a1 as r}from"./chunks/framework.CiMD_7j0.js";const m=JSON.parse('{"title":"USDT Payment & Settlement","description":"","frontmatter":{"AIGC":{"ContentProducer":"001191110102MAD55U9H0F10002","ContentPropagator":"001191110102MAD55U9H0F10002","Label":"1","ProduceID":"f952955c-9a4b-42a2-9571-6b52de9e93b1","PropagateID":"f952955c-9a4b-42a2-9571-6b52de9e93b1","ReservedCode1":"02150d77-a415-40e1-ae7a-d043e507e597","ReservedCode2":"02150d77-a415-40e1-ae7a-d043e507e597"}},"headers":[],"relativePath":"en/marketplace/settlement.md","filePath":"en/marketplace/settlement.md","lastUpdated":null}'),l={name:"en/marketplace/settlement.md"};function o(i,e,d,s,u,c){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="usdt-payment-settlement" tabindex="-1">USDT Payment &amp; Settlement <a class="header-anchor" href="#usdt-payment-settlement" aria-label="Permalink to &quot;USDT Payment &amp; Settlement&quot;">​</a></h1><h2 id="purchase" tabindex="-1">Purchase <a class="header-anchor" href="#purchase" aria-label="Permalink to &quot;Purchase&quot;">​</a></h2><p>Plugins are priced in USDT; orders are created through the LemPay <code>usdt</code> channel. The platform verifies the callback signature, merchant ID, payment type, order amount, product name and the <code>TRADE_SUCCESS</code> status. After a successful payment, a permanent plugin entitlement is created.</p><h2 id="refund-window" tabindex="-1">Refund Window <a class="header-anchor" href="#refund-window" aria-label="Permalink to &quot;Refund Window&quot;">​</a></h2><p>The refund window is configured in the admin panel. Refunds revoke the download entitlement. If developer earnings are already available, the platform must apply a corresponding reversal, so the settlement cycle should at least cover the refund risk window.</p><h2 id="developer-earnings" tabindex="-1">Developer Earnings <a class="header-anchor" href="#developer-earnings" aria-label="Permalink to &quot;Developer Earnings&quot;">​</a></h2><p>Orders record the original amount, the platform fee percentage, the platform fee and the developer earnings. After a successful payment, earnings first enter &quot;pending settlement&quot; and can only be withdrawn after the larger of the &quot;settlement cycle&quot; and the &quot;refund window&quot; has passed.</p><h2 id="withdrawal" tabindex="-1">Withdrawal <a class="header-anchor" href="#withdrawal" aria-label="Permalink to &quot;Withdrawal&quot;">​</a></h2><ul><li>Settlement currency: USDT</li><li>Network: USDT-TRC20</li><li>Minimum amount: configurable in the admin panel, default 100 USDT</li><li>Fee: fixed amount or percentage, configurable in the admin panel</li><li>Payout: manual, by an administrator</li><li>Completion: admins must fill in the TRC20 transaction hash when confirming</li></ul><p>Withdrawal status flows as &quot;Pending review → Approved, pending payout → Completed&quot;; rejection releases the frozen balance.</p>',10)])])}const p=a(l,[["render",o]]);export{m as __pageData,p as default};
